def threshold_match(e1, e2, threshold, debug=False):
    """
    Determines (according to a threshold) whether two edition representations are
    sufficiently the same. Used when importing new books to decide if an incoming
    edition matches an existing one.

    :param dict e1: dict representing an edition (expanded using expand_record)
    :param dict e2: dict representing an edition (expanded using expand_record)
    :param int threshold: each field match or difference adds or subtracts a score. Example: 875 for standard edition matching
    :param debug: Flag to enable debug mode for detailed comparison output. Defaults to False.
    :rtype: bool
    :return: Whether two editions have sufficient fields in common to be considered the same
    """
    level1 = level1_merge(e1, e2)
    total = sum(i[2] for i in level1)
    if debug:
        print(f"E1: {e1}\nE2: {e2}")
        print(f"TOTAL 1 = {total} : {level1}")
    if total >= threshold:
        return True
    level2 = level2_merge(e1, e2)
    total = sum(i[2] for i in level2)
    if debug:
        print(f"TOTAL 2 = {total} : {level2}")
    return total >= threshold


def editions_match(rec, edition, debug=False):
    if not edition.get('"'"'_is_expanded'"'"'):
        edition = expand_record(edition)
        edition['"'"'_is_expanded'"'"'] = True

    if not rec.get('"'"'_is_expanded'"'"'):
        rec = expand_record(rec)
        rec['"'"'_is_expanded'"'"'] = True

    return threshold_match(rec, edition, 875, debug) or threshold_match(rec, edition, 515, debug)
