        '"'"'peerSelectionMode'"'"': '"'"'peer_selection_mode'"'"',
    }

    api_attributes = [
        '"'"'description'"'"',
        '"'"'sourceAddress'"'"',
        '"'"'destinationAddress'"'"',
        '"'"'peerSelectionMode'"'"',
        '"'"'peers'"'"',
    ]

    returnables = [
        '"'"'description'"'"',
        '"'"'src_address'"'"',
        '"'"'dst_address'"'"',
        '"'"'peer_selection_mode'"'"',
        '"'"'peers'"'"',
    ]

    updatables = [
        '"'"'description'"'"',
        '"'"'src_address'"'"',
        '"'"'dst_address'"'"',
        '"'"'peer_selection_mode'"'"',
        '"'"'peers'"'"',
    ]


class ApiParameters(Parameters):
    @property
    def peers(self):
        if self._values['"'"'peers'"'"'] is None:
            return None
        result = sorted(self._values['"'"'peers'"'"'])
        return result


class ModuleParameters(Parameters):
    @property
    def peers(self):
        if self._values['"'"'peers'"'"'] is None:
            return None
        if len(self._values['"'"'peers'"'"']) == 1 and self._values['"'"'peers'"'"'][0] == '"'"''"'"':
            return '"'"''"'"'
        result = []
        for peer in self._values['"'"'peers'"'"']:
            result.append(fq_name(self.want.partition, peer))
        return sorted(result)

    @property
    def src_address(self):
        if self._values['"'"'src_address'"'"'] is None:
            return None
        if self._values['"'"'src_address'"'"'] == '"'"''"'"':
            return None
        return self._values['"'"'src_address'"'"']

    @property
    def dst_address(self):
        if self._values['"'"'dst_address'"'"'] is None:
            return None
        if self._values['"'"'dst_address'"'"'] == '"'"''"'"':
            return None
        return self._values['"'"'dst_address'"'"']


class Changes(Parameters):
    def to_return(self):
        result = {}
        try:
            for returnable in self.returnables:
                result[returnable] = getattr(self, returnable)
            result = self._filter_params(result)
        except Exception:
            pass
        return result


class UsableChanges(Changes):
    pass


class ReportableChanges(Changes):
    pass


class Difference(object):
    def __init__(self, want, have=None):
        self.want = want
        self.have = have

    def compare(self, param):
        try:
            result = getattr(self, param)
            return result
        except AttributeError:
            return self.__default(param)

    def __default(self, param):
        attr1 = getattr(self.want, param)
        try:
            attr2 = getattr(self.have, param)
            if attr1 != attr2:
                return attr1
        except AttributeError:
            return attr1

    @property
    def description(self):
        if self.want.description is None:
            return None
        if self.have.description is None:
            return self.want.description
        if self.want.description != self.have.description:
            return self.want.description

    @property
    def src_address(self):
        if self.want.src_address is None:
            return None
        if self.have.src_address is None:
            return self.want.src_address
        if self.want.src_address != self.have.src_address:
            return self.want.src_address

    @property
    def dst_address(self):
        if self.want.dst_address is None:
            return None
        if self.have.dst_address is None:
            return self.want.dst_address
        if self.want.dst_address != self.have.dst_address:
            return self.want.dst_address

    @property
    def peers(self):
        if self.want.peers is None:
            return None
        if self.have.peers is None:
            return self.want.peers
        if sorted(self.want.peers) != sorted(self.have.peers):
            return self.want.peers


class BaseManager(object):
    def __init__(self, *args, **kwargs):
        self.module = kwargs.get('"'"'module'"'"', None)
        self.client = F5RestClient(**self.module.params)
        self.want = ModuleParameters(params=self.module.params)
        self.have = ApiParameters()
        self.changes = UsableChanges()

    def _set_changed_options(self):
        changed = {}
        for key in Parameters.returnables:
            if getattr(self.want, key) is not None:
                changed[key] = getattr(self.want, key)
        if changed:
            self.changes = UsableChanges(params=changed)

    def _update_changed_options(self):
        diff = Difference(self.want, self.have)
        updatables = Parameters.updatables
        changed = dict()
        for k in updatables:
            change = diff.compare(k)
            if change is None:
                continue
            else:
                if isinstance(change, dict):
                    changed.update(change)
                else:
                    changed[k] = change
        if changed:
            self.changes = UsableChanges(params=changed)
            return True
        return False

    def should_update(self):
        result = self._update_changed_options()
        if result:
            return True
        return False

    def exec_module(self):
        changed = False
        result = dict()
        state = self.want.state

        if state == "present":
            changed = self.present()
        elif state == "absent":
            changed = self.absent()

        reportable = ReportableChanges(params=self.changes.to_return())
        changes = reportable.to_return()
        result.update(**changes)
        result.update(dict(changed=changed))
        self._announce_deprecations(result)
        return result

    def _announce_deprecations(self, result):
        warnings = result.pop('"'"'__warnings'"'"', [])
        for warning in warnings:
            self.client.module.deprecate(
                msg=warning['"'"'msg'"'"'],
                version=warning['"'"'version'"'"']
            )

    def present(self):
        if self.exists():
            return self.update()
        else:
            return self.create()

    def absent(self):
        if self.exists():
            return self.remove()
        return False

    def update(self):
        self.have = self.read_current_from_device()
        if not self.should_update():
            return False
        if self.module.check_mode:
            return True
        self.update_on_device()
        return True

    def remove(self):
        if self.module.check_mode:
            return True
        self.remove_from_device()
        if self.exists():
            raise F5ModuleError("Failed to delete the resource.")
        return True

    def create(self):
        self._set_changed_options()
        if self.module.check_mode:
            return True
        self.create_on_device()
        return True


class GenericModuleManager(BaseManager):
    def exists(self):
        uri = "https://{0}:{1}/mgmt/tm/ltm/message-routing/generic/route/~{2}~{3}".format(
            self.client.provider['"'"'server'"'"'],
            self.client.provider['"'"'server_port'"'"'],
            transform_name(self.want.partition, self.want.name)
        )
        resp = self.client.api.get(uri)
        try:
            response = resp.json()
        except ValueError:
            return False
        if resp.status == 404 or '"'"'code'"'"' in response and response['"'"'code'"'"'] == 404:
            return False
        return True

    def create_on_device(self):
        params = self.changes.api_params()
        params['"'"'name'"'"'] = self.want.name
        params['"'"'partition'"'"'] = self.want.partition
        uri = "https://{0}:{1}/mgmt/tm/ltm/message-routing/generic/route/".format(
            self.client.provider['"'"'server'"'"'],
            self.client.provider['"'"'server_port'"'"'],
        )

        resp = self.client.api.post(uri, json=params)

        try:
            response = resp.json()
        except ValueError as ex:
            raise F5ModuleError(str(ex))

        if '"'"'code'"'"' in response and response['"'"'code'"'"'] in [400, 403]:
            if '"'"'message'"'"' in response:
                raise F5ModuleError(response['"'"'message'"'"'])
            else:
                raise F5ModuleError(resp.content)
        return response['"'"'selfLink'"'"']

    def update_on_device(self):
        params = self.changes.api_params()
        uri = "https://{0}:{1}/mgmt/tm/ltm/message-routing/generic/route/~{2}~{3}".format(
            self.client.provider['"'"'server'"'"'],
            self.client.provider['"'"'server_port'"'"'],
            transform_name(self.want.partition, self.want.name)
        )
        resp = self.client.api.patch(uri, json=params)
        try:
            response = resp.json()
        except ValueError as ex:
            raise F5ModuleError(str(ex))

        if '"'"'code'"'"' in response and response['"'"'code'"'"'] == 400:
            if '"'"'message'"'"' in response:
                raise F5ModuleError(response['"'"'message'"'"'])
            else:
                raise F5ModuleError(resp.content)

    def remove_from_device(self):
        uri = "https://{0}:{1}/mgmt/tm/ltm/message-routing/generic/route/~{2}~{3}".format(
            self.client.provider['"'"'server'"'"'],
            self.client.provider['"'"'server_port'"'"'],
            transform_name(self.want.partition, self.want.name)
        )
        response = self.client.api.delete(uri)
        if response.status == 200:
            return True
        raise F5ModuleError(response.content)

    def read_current_from_device(self):
        uri = "https://{0}:{1}/mgmt/tm/ltm/message-routing/generic/route/~{2}~{3}".format(
            self.client.provider['"'"'server'"'"'],
            self.client.provider['"'"'server_port'"'"'],
            transform_name(self.want.partition, self.want.name)
        )
        resp = self.client.api.get(uri)
        try:
            response = resp.json()
        except ValueError as ex:
            raise F5ModuleError(str(ex))

        if '"'"'code'"'"' in response and response['"'"'code'"'"'] == 400:
            if '"'"'message'"'"' in response:
                raise F5ModuleError(response['"'"'message'"'"'])
            else:
                raise F5ModuleError(resp.content)
        return ApiParameters(params=response)


class ModuleManager(object):
    def __init__(self, *args, **kwargs):
        self.module = kwargs.get('"'"'module'"'"', None)
        self.client = F5RestClient(**self.module.params)
        self.kwargs = kwargs

    def version_less_than_14(self):
        version = tmos_version(self.client)
        if LooseVersion(version) < LooseVersion('"'"'14.0.0'"'"'):
            return True
        return False

    def exec_module(self):
        if self.version_less_than_14():
            raise F5ModuleError(
                '"'"'Message routing is not supported on TMOS version below 14.x'"'"'
            )
        manager = self.get_manager('"'"'generic'"'"')
        return manager.exec_module()

    def get_manager(self, type):
        if type == '"'"'generic'"'"':
            return GenericModuleManager(module=self.module, client=self.client)
        raise F5ModuleError(
            '"'"'The provided route type is not supported'"'"'
        )


class ArgumentSpec(object):
    def __init__(self):
        self.supports_check_mode = True
        argument_spec = dict(
            name=dict(required=True),
            description=dict(),
            src_address=dict(),
            dst_address=dict(),
            peer_selection_mode=dict(
                choices=['"'"'ratio'"'"', '"'"'sequential'"'"']
            ),
            peers=dict(type='"'"'list'"'"'),
            partition=dict(
                default='"'"'Common'"'"',
                fallback=(env_fallback, ['"'"'F5_PARTITION'"'"'])
            ),
            state=dict(
                default='"'"'present'"'"',
                choices=['"'"'present'"'"', '"'"'absent'"'"']
            )
        )
        self.argument_spec = {}
        self.argument_spec.update(f5_argument_spec)
        self.argument_spec.update(argument_spec)


def main():
    spec = ArgumentSpec()

    module = AnsibleModule(
        argument_spec=spec.argument_spec,
        supports_check_mode=spec.supports_check_mode
    )

    try:
        mm = ModuleManager(module=module)
        results = mm.exec_module()
        module.exit_json(**results)
    except F5ModuleError as ex:
        module.fail_json(msg=str(ex))


if __name__ == '"'"'__main__'"'"':
    main()'"}]

