    def process_rhs(self, compiler, connection):
        if not connection.features.has_native_json_field:
            # For databases without native JSON support, use the same path extraction
            # as KeyTransformExact
            if connection.vendor == '"'"'mysql'"'"':
                return super().process_rhs(compiler, connection)
            elif connection.vendor == '"'"'oracle'"'"':
                return super().process_rhs(compiler, connection)
            elif connection.vendor == '"'"'sqlite'"'"':
                return super().process_rhs(compiler, connection)
        return super().process_rhs(compiler, connection)

    def as_sql(self, compiler, connection):
        lhs_sql, params = self.process_lhs(compiler, connection)
        rhs_sql, rhs_params = self.process_rhs(compiler, connection)
        params.extend(rhs_params)

        if not connection.features.has_native_json_field:
            if connection.vendor == '"'"'mysql'"'"':
                return '"'"'JSON_CONTAINS(%s, %%s, %%s)'"'"' % lhs_sql, params
            elif connection.vendor == '"'"'oracle'"'"':
                return '"'"'JSON_EXISTS(%s, %%s)'"'"' % lhs_sql, params
            elif connection.vendor == '"'"'sqlite'"'"':
                return '"'"'JSON_EXTRACT(%s, %%s) IN %%s'"'"' % lhs_sql, params

        return super().as_sql(compiler, connection)'"},{"step":28,"planner_type":"refiner","rule_ids":["dwell_V"],"content":"[Plan Refiner Guidance]

